void PLAT_free(void* ptr)
{
  UNITY_LINE_TYPE cmock_line = TEST_LINE_NUM;
  CMOCK_PLAT_free_CALL_INSTANCE* cmock_call_instance;
  UNITY_SET_DETAIL(CMockString_PLAT_free);
  cmock_call_instance = (CMOCK_PLAT_free_CALL_INSTANCE*)CMock_Guts_GetAddressFor(Mock.PLAT_free_CallInstance);
  Mock.PLAT_free_CallInstance = CMock_Guts_MemNext(Mock.PLAT_free_CallInstance);
  if (Mock.PLAT_free_IgnoreBool && cmock_call_instance != NULL &&
      cmock_call_instance->ReturnThruPtr_ptr_Used)
  {
    UNITY_TEST_ASSERT_NOT_NULL(ptr, cmock_line, CMockStringPtrIsNULL);
    CMOCK_MEMCPY((void*)ptr, (const void*)cmock_call_instance->ReturnThruPtr_ptr_Val,
      cmock_call_instance->ReturnThruPtr_ptr_Size);
  }
  if (Mock.PLAT_free_IgnoreBool)
  {
    UNITY_CLR_DETAILS();
    return;
  }
  if (!Mock.PLAT_free_CallbackBool &&
      Mock.PLAT_free_CallbackFunctionPointer != NULL)
  {
    Mock.PLAT_free_CallbackFunctionPointer(ptr, Mock.PLAT_free_CallbackCalls++);
    UNITY_CLR_DETAILS();
    return;
  }
  UNITY_TEST_ASSERT_NOT_NULL(cmock_call_instance, cmock_line, CMockStringCalledMore);
  cmock_line = cmock_call_instance->LineNumber;
  if (cmock_call_instance->CallOrder > ++GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledEarly);
  if (cmock_call_instance->CallOrder < GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledLate);
  if (!cmock_call_instance->ExpectAnyArgsBool)
  {
  if (!cmock_call_instance->IgnoreArg_ptr)
  {
    UNITY_SET_DETAILS(CMockString_PLAT_free,CMockString_ptr);
    UNITY_TEST_ASSERT_EQUAL_PTR(cmock_call_instance->Expected_ptr, ptr, cmock_line, CMockStringMismatch);
  }
  }
  if (Mock.PLAT_free_CallbackFunctionPointer != NULL)
  {
    UNITY_SET_DETAIL(CMockString_PLAT_free);
    Mock.PLAT_free_CallbackFunctionPointer(ptr, Mock.PLAT_free_CallbackCalls++);
  }
  if (cmock_call_instance->ReturnThruPtr_ptr_Used)
  {
    UNITY_TEST_ASSERT_NOT_NULL(ptr, cmock_line, CMockStringPtrIsNULL);
    CMOCK_MEMCPY((void*)ptr, (const void*)cmock_call_instance->ReturnThruPtr_ptr_Val,
      cmock_call_instance->ReturnThruPtr_ptr_Size);
  }
  UNITY_CLR_DETAILS();
}

